<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {Bot,Plus,ArrowLeft,MessageCircle,Mic,BookOpen,ShieldCheck,SlidersHorizontal,Play,Pause,Save,X,Trash2,Phone,Headphones,Check,Send,Volume2,Settings2,Sparkles,Clock,ExternalLink} from 'lucide-vue-next'
defineEmits(['supervise'])
const data=ref({agents:[],queues:[],senders:[],bindings:[],sessions:[],connection:{prices:{}}}),selected=ref(null),config=ref(null),tab=ref('identity'),busy=ref(false),error=ref(''),notice=ref(''),baseline=ref(''),testOpen=ref(false),connectionOpen=ref(false),leaveAction=ref(null),testMode=ref('local'),session=ref(null),messages=ref([]),input=ref(''),consent=ref(false),key=ref(''),enabled=ref(false),daily=ref(100),voiceStatus=ref('idle'),voiceTranscript=ref(''),sender=ref(''),bindConsent=ref(false),history=ref(null)
const sipSecret=ref(''),projectId=ref(''),sipSetup=ref(null),sipQueue=ref(''),sipTransfer=ref(''),sipEnabled=ref(false),sipConsent=ref(false)
const dirty=computed(()=>config.value&&JSON.stringify(config.value)!==baseline.value)
const tabs=[['identity','Identidade',Bot],['knowledge','Conhecimento',BookOpen],['behavior','Conversa e limites',ShieldCheck],['voice','Voz e idiomas',Volume2],['channels','Canais',MessageCircle]]
const locales={'pt-BR':'Português brasileiro','en-US':'Inglês americano','es-MX':'Espanhol latino-americano'}
const scenario=ref(null)
const scenarios=[
 {id:'rush',label:'Pressa',expect:'Ir direto ao próximo passo, sem pular confirmações.',phrases:{'pt-BR':'Tenho só um minuto. Pode ir direto ao ponto?','en-US':'I only have a minute. Can you get straight to the point?','es-MX':'Solo tengo un minuto. ¿Puedes ir directo al punto?'}},
 {id:'frustration',label:'Reclamação',expect:'Reconhecer o problema concreto e oferecer somente soluções aprovadas.',phrases:{'pt-BR':'Já expliquei isso três vezes e ninguém resolveu. Estou frustrado.','en-US':'I have explained this three times and nobody has fixed it. I am frustrated.','es-MX':'Ya expliqué esto tres veces y nadie lo ha resuelto. Estoy frustrado.'}},
 {id:'confusion',label:'Dúvida',expect:'Explicar um ponto por vez e conferir o entendimento.',phrases:{'pt-BR':'Não entendi essa parte. Pode explicar de outro jeito?','en-US':'I did not understand that part. Could you explain it another way?','es-MX':'No entendí esa parte. ¿Puedes explicarlo de otra manera?'}},
 {id:'conflict',label:'Conflito',expect:'Manter serenidade, evitar discussão e oferecer ajuda humana.',phrases:{'pt-BR':'Esse atendimento é péssimo! Vocês nunca resolvem nada!','en-US':'This service is terrible! You never solve anything!','es-MX':'¡Este servicio es pésimo! ¡Nunca resuelven nada!'}},
 {id:'human',label:'Quero uma pessoa',expect:'Respeitar o pedido e encaminhar sem insistir nem prometer transferência concluída.',phrases:{'pt-BR':'Quero falar com uma pessoa agora, por favor.','en-US':'I want to speak to a human now, please.','es-MX':'Quiero hablar con una persona ahora, por favor.'}},
 {id:'stop',label:'Encerrar contato',expect:'Interromper a abordagem sem tentar recuperar a venda.',phrases:{'pt-BR':'Não quero mais receber mensagens. Pare de me contatar.','en-US':'Stop contacting me. Do not send me any more messages.','es-MX':'No quiero recibir más mensajes. No me contacten más.'}}
]
function chooseScenario(item){scenario.value=item;if(testMode.value!=='voice')input.value=item.phrases[config.value.language]}
const canPremium=computed(()=>data.value.connection.text_enabled??data.value.connection.enabled)
const canVoice=computed(()=>data.value.connection.voice_enabled??data.value.connection.enabled)
let peer=null,stream=null,audio=null,dc=null,voiceId=null,voiceTimer=null,connecting=false
async function api(path,method='GET',body){const r=await fetch('/api/ai'+path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' · '):d.message||'Não foi possível concluir.');return d}
async function run(fn){busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){data.value=await api('/agents');enabled.value=data.value.connection.enabled;daily.value=data.value.connection.daily_requests}
onMounted(()=>run(load))
function select(a){sipSetup.value=null;const sb=data.value.sip_bindings?.find(b=>b.agent_id===a.id);sipQueue.value=sb?.queue_id||'';sipTransfer.value=sb?.transfer_uri||'';sipEnabled.value=!!sb?.enabled;sipConsent.value=false;selected.value=a;config.value=JSON.parse(JSON.stringify(a.draft));baseline.value=JSON.stringify(config.value);tab.value='identity';sender.value='';bindConsent.value=false}
function requestLeave(fn){if(dirty.value||voiceStatus.value!=='idle'){leaveAction.value=fn;return}fn()}
defineExpose({requestLeave})
async function discard(){await stopVoice();const fn=leaveAction.value;leaveAction.value=null;baseline.value=JSON.stringify(config.value);fn?.()}
function back(){requestLeave(()=>{selected.value=null;config.value=null})}
async function create(kind){await run(async()=>{const c=JSON.parse(JSON.stringify(data.value.defaults));c.name={reception:'Recepção virtual',sales:'SDR de vendas',support:'Assistente de atendimento',adaptive:'Assistente de relacionamento'}[kind];c.purpose={reception:'Receber clientes, entender o motivo do contato e orientar o próximo passo.',sales:'Entender a necessidade, qualificar interesse e coletar a preferência de contato com a equipe comercial.',support:'Responder dúvidas com a base aprovada e encaminhar casos que exigem análise humana.',adaptive:'Entender a necessidade, adaptar a conversa ao ritmo e às preferências do cliente e conduzir dúvidas, reclamações e conflitos com respeito e apoio humano quando necessário.'}[kind];c.adaptive_conversation=kind==='adaptive';c.questions=kind==='sales'?['O que você procura resolver?','Qual é o melhor horário para nossa equipe conversar com você?']:[];const a=await api('/agents','POST',{config:c});await load();select(a)})}
async function save(){const a=await api('/agents/'+selected.value.id,'PUT',{config:config.value,revision:selected.value.revision});selected.value=a;baseline.value=JSON.stringify(config.value);await load();notice.value='Rascunho salvo.'}
async function publish(){await run(async()=>{if(dirty.value)await save();const a=await api('/agents/'+selected.value.id+'/publish','POST',{revision:selected.value.revision});selected.value=a;await load();notice.value='Versão '+a.published_version+' publicada. Canais são ativados separadamente.'})}
async function togglePause(a){await run(async()=>{const next=await api('/agents/'+a.id+'/pause','POST',{paused:!a.paused});if(selected.value?.id===a.id)selected.value=next;await load()})}
function settings(){sipSecret.value='';projectId.value=data.value.connection.project_id||'';key.value='';consent.value=false;connectionOpen.value=true}
async function saveConnection(){await run(async()=>{await api('/connection','PUT',{api_key:key.value||null,sip_secret:sipSecret.value||null,project_id:projectId.value||null,enabled:enabled.value,daily_requests:Number(daily.value),cost_acknowledged:consent.value});key.value='';connectionOpen.value=false;await load();notice.value='Conexão salva. Testes e canais têm ativação própria.'})}
async function openTest(){await run(async()=>{if(dirty.value)await save();testOpen.value=true;scenario.value=null;input.value='';session.value=null;messages.value=[];voiceTranscript.value='';testMode.value='local';consent.value=false})}
async function startText(){await run(async()=>{session.value=await api('/agents/'+selected.value.id+'/start','POST',{mode:testMode.value,cost_acknowledged:consent.value});messages.value=[{role:'assistant',text:session.value.greeting}];notice.value=''})}
async function send(){if(!input.value.trim())return;const text=input.value;input.value='';messages.value.push({role:'user',text});await run(async()=>{const t=await api('/sessions/'+session.value.id+'/turn','POST',{request_id:crypto.randomUUID(),input:text});messages.value.push({role:'assistant',text:t.output,action:t.action,latency:t.latency_ms});if(t.action!=='reply')session.value={...session.value,ended:true};await load()})}
async function bind(enabled){await run(async()=>{await api('/agents/'+selected.value.id+'/binding','POST',{sender_id:Number(sender.value),enabled,cost_acknowledged:bindConsent.value});await load();notice.value=enabled?'IA ativada para novas mensagens recebidas nesse número.':'Atendimento automático desativado.'})}
async function prepareSip(){await run(async()=>{sipSetup.value=await api('/agents/'+selected.value.id+'/sip','POST',{queue_id:Number(sipQueue.value),transfer_uri:sipTransfer.value||null,enabled:sipEnabled.value,rotate:false,cost_acknowledged:sipConsent.value});await load();notice.value='Rota SIP salva. A operadora ou o PABX deve encaminhar o áudio para o destino indicado.'})}
async function inspect(id){await run(async()=>{history.value=await api('/sessions/'+id)})}
async function stopVoice(){connecting=false;clearTimeout(voiceTimer);voiceTimer=null;dc?.close();dc=null;peer?.close();peer=null;stream?.getTracks().forEach(t=>t.stop());stream=null;if(audio){audio.pause();audio.srcObject=null;audio=null}const id=voiceId;voiceId=null;voiceStatus.value='idle';if(id)try{await api('/sessions/'+id+'/close','POST',{})}catch{error.value='O áudio local foi encerrado. A confirmação do provedor será repetida pelo servidor.'}}
async function startVoice(){if(!consent.value||!canVoice.value)return;await run(async()=>{voiceStatus.value='connecting';connecting=true;try{stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});if(!connecting){stream.getTracks().forEach(t=>t.stop());return}peer=new RTCPeerConnection();audio=new Audio();audio.autoplay=true;peer.ontrack=e=>{audio.srcObject=e.streams[0];audio.play().catch(()=>{error.value='Permita a reprodução de áudio para ouvir o agente.'})};stream.getTracks().forEach(t=>peer.addTrack(t,stream));dc=peer.createDataChannel('oai-events');dc.onmessage=e=>{try{const v=JSON.parse(e.data);if(v.type==='input_audio_buffer.speech_started')voiceStatus.value='listening';if(v.type==='response.output_audio_transcript.delta'){voiceStatus.value='speaking';voiceTranscript.value+=v.delta||''}if(v.type==='response.output_audio_transcript.done')voiceTranscript.value+='\n';if(v.type==='response.done')voiceStatus.value='listening';if(v.type==='error'){error.value='A sessão de voz encontrou um erro. Encerre e confira a conexão.';stopVoice()}}catch{}};dc.onopen=()=>{voiceStatus.value='listening';dc.send(JSON.stringify({type:'response.create',response:{instructions:'Cumprimente o cliente com esta saudação e aguarde: '+config.value.greeting}}))};peer.onconnectionstatechange=()=>{if(['failed','closed'].includes(peer?.connectionState))stopVoice()};const offer=await peer.createOffer();await peer.setLocalDescription(offer);const answer=await api('/agents/'+selected.value.id+'/voice','POST',{sdp:offer.sdp,cost_acknowledged:consent.value});voiceId=answer.id;if(!connecting){await stopVoice();return}await peer.setRemoteDescription({type:'answer',sdp:answer.sdp});voiceTimer=setTimeout(stopVoice,config.value.max_seconds*1000)}catch(e){await stopVoice();throw e}})}
async function closeTest(){error.value='';await stopVoice();testOpen.value=false}
onBeforeUnmount(()=>stopVoice())
</script>
<template>
 <div class="ai-studio">
  <header class="ai-heading"><div><span class="eyebrow">CONVERSAS COM PROPÓSITO</span><h1>Agentes de IA</h1><p>Uma identidade. Conhecimento da sua empresa. Conversas por voz e WhatsApp.</p></div><button class="secondary" @click="$emit('supervise')"><MessageCircle :size="16"/>Acompanhar conversas</button><a v-if="data.connection.administration_url" class="secondary ai-admin-link" :href="data.connection.administration_url" target="_blank" rel="noopener">Administrar IA ↗</a><button v-if="data.connection.can_configure!==false" class="secondary" @click="settings"><Settings2 :size="16"/>Conexão e custos</button></header>
  <div v-if="error" class="ai-error" role="alert">{{error}}</div><div v-if="notice" class="ai-notice" role="status">{{notice}}</div>
  <template v-if="!selected">
   <div class="ai-intro"><div class="ai-orb"><Sparkles :size="32"/></div><div><h2>Seu próximo atendimento começa aqui.</h2><p>Escolha um ponto de partida, ensine o que importa e experimente antes de ativar.</p></div><span :class="['ai-pill',canPremium?'good':'']">{{canPremium?'Atendimento escrito disponível':'Aguardando liberação'}}</span></div>
   <div class="ai-presets"><button v-for="p in [['reception','Recepção','Receba, entenda e encaminhe.'],['sales','SDR de vendas','Qualifique interesse sem perder o contexto.'],['support','Atendimento','Responda com informações aprovadas.'],['adaptive','Atendimento adaptativo','Ajuste a conversa ao ritmo e ao contexto.']]" :key="p[0]" @click="create(p[0])" :disabled="busy"><span class="ai-small-icon"><Plus :size="19"/></span><strong>{{p[1]}}</strong><small>{{p[2]}}</small></button></div>
   <div class="ai-section-title"><h2>Seus agentes</h2><span>{{data.agents.length}} configurado(s)</span></div>
   <div v-if="!data.agents.length" class="ai-empty"><Bot :size="42"/><h3>Crie seu primeiro agente</h3><p>Comece por um dos modelos acima. Nenhum canal será ativado automaticamente.</p></div>
   <div class="ai-cards"><article v-for="a in data.agents" :key="a.id"><div class="ai-card-top"><span class="ai-avatar"><Bot :size="26"/></span><span :class="['ai-pill',a.paused?'':a.published_version?'good':'']">{{a.paused?'Pausado':a.published_version?'Publicado · v'+a.published_version:'Rascunho'}}</span></div><h2>{{a.name}}</h2><p>{{a.draft.purpose}}</p><div class="ai-tags"><span>{{locales[a.draft.language]}}</span><span v-if="a.draft.adaptive_conversation"><Sparkles :size="12"/>Adaptativo</span><span><Mic :size="12"/>Voz</span><span><MessageCircle :size="12"/>WhatsApp</span></div><footer><button class="primary" @click="select(a)">Configurar agente</button><button class="secondary" @click="togglePause(a)" :disabled="busy"><Play v-if="a.paused" :size="14"/><Pause v-else :size="14"/>{{a.paused?'Despausar':'Pausar'}}</button></footer></article></div>
   <div v-if="data.sessions.length" class="ai-history"><div class="ai-section-title"><h2>Conversas e testes recentes</h2><button class="secondary" @click="run(load)">Atualizar</button></div><button v-for="s in data.sessions" :key="s.id" @click="inspect(s.id)"><span><strong>{{data.agents.find(a=>a.id===s.agent_id)?.name||'Agente'}}</strong><small>{{s.mode==='local'?'Simulação local':s.channel==='whatsapp'?'WhatsApp':s.channel==='phone'?'Telefonia SIP':'Teste com IA'}} · {{['voice','phone'].includes(s.channel)?'Voz':'Texto'}}</small></span><span class="ai-pill">{{({open:'Em andamento',closed:'Encerrada',handoff:'Passagem humana',stop:'Descadastro',failed:'Falha',closing:'Encerrando',connecting:'Conectando',transferring:'Transferindo',transferred:'Transferência solicitada'})[s.status]||s.status}}</span><small>{{['voice','phone'].includes(s.channel)?'Consumo no provedor':s.provider==='qwen'?'Infraestrutura própria':'US$ '+Number(s.estimated_usd).toFixed(6)}}</small></button></div>
  </template>
  <template v-else>
   <div class="ai-editor-top"><button class="secondary" @click="back"><ArrowLeft :size="15"/>Meus agentes</button><span>{{dirty?'Alterações não salvas':'Rascunho salvo'}} · {{selected.published_version?'versão publicada '+selected.published_version:'ainda não publicado'}}</span><button class="secondary" @click="run(save)" :disabled="busy||!dirty"><Save :size="15"/>Salvar</button><button class="secondary" @click="openTest" :disabled="busy"><Play :size="15"/>Testar agente</button><button class="primary" @click="publish" :disabled="busy">Publicar versão</button></div>
   <div class="ai-editor"><nav aria-label="Configuração do agente"><button v-for="[id,label,icon] in tabs" :class="{active:tab===id}" @click="tab=id"><component :is="icon" :size="18"/>{{label}}</button></nav><div class="ai-editor-body">
    <section v-if="tab==='identity'"><span class="eyebrow">01 · IDENTIDADE</span><h2>Quem conversa com seu cliente?</h2><p class="ai-help">Um objetivo claro ajuda o agente a ser útil e consistente.</p><label>Nome do agente<input v-model="config.name" maxlength="120" placeholder="Ex.: Sofia · Atendimento"></label><label>O que ele deve resolver?<textarea v-model="config.purpose" rows="3" maxlength="1500"/></label><label>Primeira mensagem<textarea v-model="config.greeting" rows="3" maxlength="500"/></label><div class="ai-note"><ShieldCheck :size="17"/>O agente se identifica como assistente virtual. Naturalidade na voz não significa se passar por uma pessoa.</div><label>Estilo de conversa<select v-model="config.tone"><option value="friendly">Acolhedor e natural</option><option value="professional">Profissional e objetivo</option><option value="concise">Direto e breve</option></select></label></section>
    <section v-if="tab==='knowledge'"><span class="eyebrow">02 · CONHECIMENTO</span><h2>Ensine com informações aprovadas.</h2><p class="ai-help">Preços, horários, produtos e políticas. Se a informação não estiver aqui, o agente pede ajuda à equipe.</p><article v-for="(k,i) in config.knowledge" :key="i" class="ai-knowledge"><div><strong>Informação {{i+1}}</strong><button :aria-label="'Excluir informação '+(i+1)" @click="config.knowledge.splice(i,1)"><Trash2 :size="16"/></button></div><label>Pergunta ou assunto<input v-model="k.question" maxlength="300" placeholder="Qual é o horário de atendimento?"></label><label>Resposta aprovada<textarea v-model="k.answer" rows="3" maxlength="2000" placeholder="Escreva a informação que o agente pode utilizar."/></label></article><button class="secondary" :disabled="config.knowledge.length>=30" @click="config.knowledge.push({question:'',answer:''})"><Plus :size="16"/>Adicionar informação</button><div class="ai-note">As informações ficam exclusivas desta empresa. Alterações só chegam aos canais depois de publicar uma nova versão.</div></section>
    <section v-if="tab==='behavior'"><span class="eyebrow">03 · CONVERSA E LIMITES</span><h2>Conduza a conversa com clareza.</h2><p class="ai-help">O agente faz uma pergunta por vez e respeita os pedidos para falar com uma pessoa ou interromper o contato.</p><div class="ai-adaptive"><div class="ai-adaptive-heading"><span class="ai-small-icon"><Sparkles :size="20"/></span><div><h3>Uma conversa atenta ao cliente</h3><p>Respostas mais breves para quem tem pressa, explicações claras para quem tem dúvidas e acolhimento diante de uma reclamação.</p></div></div><label class="ai-check"><input type="checkbox" v-model="config.adaptive_conversation">Adaptar ao ritmo e ao contexto</label><div v-if="config.adaptive_conversation" class="ai-tags"><span>Pressa</span><span>Dúvidas</span><span>Reclamações</span><span>Conflitos</span></div><p class="ai-help">No WhatsApp, considera o texto. Na telefonia, também pode considerar ritmo, pausas e entonação. São sinais sujeitos a erro: o que o cliente declara e prefere vem primeiro. Sem diagnósticos nem perfil emocional.</p><p v-if="config.adaptive_conversation" class="ai-help">Pedidos de humano ou de interrupção têm prioridade. A adaptação preserva as regras, os preços e as permissões da empresa.</p></div><label>Orientações da empresa<textarea v-model="config.rules" maxlength="2000" rows="4"/></label><h3>Perguntas de qualificação</h3><div v-for="(q,i) in config.questions" :key="i" class="ai-inline"><input v-model="config.questions[i]" maxlength="300" :aria-label="'Pergunta '+(i+1)"><button @click="config.questions.splice(i,1)" aria-label="Excluir pergunta"><X :size="16"/></button></div><button class="secondary" :disabled="config.questions.length>=10" @click="config.questions.push('')"><Plus :size="15"/>Adicionar pergunta</button><hr><label>Fila para a equipe humana<select v-model="config.handoff_queue_id"><option :value="null">Selecionar fila</option><option v-for="q in data.queues" :value="q.id">{{q.name}}</option></select></label><label>Quando precisar de ajuda<textarea v-model="config.unknown_reply" rows="2" maxlength="500"/></label><p class="ai-help">A passagem depende da disponibilidade da equipe. O agente não confirma agendamentos nem executa ações externas sem uma integração.</p><div class="ai-two"><label>Máximo de respostas por conversa<input type="number" v-model.number="config.max_turns" min="2" max="30"></label><label>Duração máxima da voz (segundos)<input type="number" v-model.number="config.max_seconds" min="60" max="600"></label></div></section>
    <section v-if="tab==='voice'"><span class="eyebrow">04 · VOZ E IDIOMAS</span><h2>Uma conversa que respeita o ritmo.</h2><p class="ai-help">Voz em tempo real com escuta, resposta e interrupção. Compare a pronúncia no teste com seu microfone.</p><div class="ai-two"><label>Idioma principal<select v-model="config.language"><option v-for="(label,id) in locales" :value="id">{{label}}</option></select></label><label>Voz do agente<select v-model="config.voice"><option value="marin">Marin</option><option value="cedar">Cedar</option><option value="coral">Coral</option><option value="sage">Sage</option><option value="ash">Ash</option></select></label></div><label>Velocidade · {{config.speed}}×<input type="range" v-model.number="config.speed" min="0.8" max="1.2" step="0.05"></label><label>Tempo para ouvir antes de responder<select v-model="config.patience"><option value="low">Mais ágil</option><option value="medium">Equilibrado</option><option value="high">Mais paciente</option></select></label><label class="ai-check"><input type="checkbox" v-model="config.interruptions">Permitir que o cliente interrompa a fala do agente</label><details><summary>Pronúncia de marcas, nomes e termos</summary><div v-for="(p,i) in config.pronunciations" class="ai-inline"><input v-model="p.term" placeholder="Termo" aria-label="Termo"><input v-model="p.spoken" placeholder="Como falar" aria-label="Pronúncia"><button @click="config.pronunciations.splice(i,1)" aria-label="Excluir pronúncia"><X :size="15"/></button></div><button class="secondary" :disabled="config.pronunciations.length>=20" @click="config.pronunciations.push({term:'',spoken:''})">Adicionar pronúncia</button></details><div class="ai-note"><Headphones :size="20"/>Kokoro e Chatterbox continuam no Estúdio de voz para recados e áudios gerados. Para conversar ao vivo, este agente usa a conexão de voz liberada pela administração.</div><button class="primary" @click="openTest">Experimentar a conversa</button></section>
    <section v-if="tab==='channels'"><span class="eyebrow">05 · CANAIS</span><h2>Ative onde faz sentido.</h2><p class="ai-help">Publicar o agente não inicia chamadas nem envia mensagens. Cada canal tem seu próprio vínculo.</p><article class="ai-channel"><MessageCircle :size="25"/><div><h3>WhatsApp</h3><p>Responda a novas mensagens recebidas. A equipe pode assumir a conversa a qualquer momento.</p></div></article><label>Número da empresa<select v-model="sender"><option value="">Selecionar número</option><option v-for="s in data.senders" :value="s.id">{{s.label}} · {{s.number}}</option></select></label><div v-for="b in data.bindings.filter(b=>b.agent_id===selected.id)" class="ai-note">{{data.senders.find(s=>s.id===b.sender_id)?.number}} · {{b.enabled?'Automático ativado':'Desativado'}}</div><label class="ai-check"><input type="checkbox" v-model="bindConsent">Testei o agente e autorizo respostas automáticas neste número.</label><div class="ai-inline"><button class="primary" :disabled="busy||!sender||!bindConsent||!canPremium||!selected.published_version||dirty" @click="bind(true)">Ativar no WhatsApp</button><button class="secondary" :disabled="busy||!sender||!bindConsent" @click="bind(false)">Desativar</button></div><p class="ai-help">Respeita descadastro, janela de resposta, limites e destinos autorizados do canal. Conversas assumidas por pessoas permanecem com a equipe.</p><hr><article class="ai-channel"><Phone :size="25"/><div><h3>Telefonia</h3><p>Conecte a operadora ou o Asterisk por SIP/TLS. A voz usa o mesmo agente publicado; o número continua com sua operadora.</p><span :class="['ai-pill',data.telephony?.ready?'good':'']">{{data.telephony?.ready?'Serviço de voz conectado':'Serviço de voz a configurar'}}</span></div></article><p v-if="data.connection.can_manage_telephony===false" class="ai-help">A conexão de telefonia é preparada pela administração DiscAI.</p><details v-if="data.connection.can_manage_telephony!==false"><summary>Configurar rota de telefonia</summary><p class="ai-help">Uma configuração inicial feita pelo responsável pela telefonia. Não altera números nem filas existentes.</p><label>Fila de atendimento<select v-model="sipQueue"><option value="">Selecionar fila</option><option v-for="q in data.queues" :value="q.id">{{q.name}}</option></select></label><label>Destino SIP para passagem humana (opcional)<input v-model="sipTransfer" placeholder="sip:fila@seu-pabx.example" maxlength="250"></label><p class="ai-help">O destino deve encaminhar à fila escolhida no PABX. A transferência só é solicitada quando há atendente disponível nessa fila.</p><label class="ai-check"><input type="checkbox" v-model="sipEnabled">Ativar recebimento por IA nesta rota após homologação</label><label class="ai-check"><input type="checkbox" v-model="sipConsent">Conferi os custos e a configuração da rota.</label><button class="primary" @click="prepareSip" :disabled="busy||!sipQueue||!sipConsent||dirty">Salvar rota SIP</button><div v-if="sipSetup" class="ai-price"><strong>Configuração para o PABX / operadora</strong><span>Destino TLS: <code>{{sipSetup.sip_uri}}</code></span><span>Webhook do projeto OpenAI: <code>{{sipSetup.webhook_url}}</code></span><span v-if="sipSetup.route_token">Cabeçalho X-DiscAI-Route: <code>{{sipSetup.route_token}}</code></span><small v-if="sipSetup.route_token">Copie este segredo agora: ele não será mostrado novamente. Use-o apenas no tronco autorizado.</small><small>Inscreva o webhook em realtime.call.incoming. A rota só recebe quando a entrada da fila está habilitada e dentro do horário.</small></div></details></section>
   </div></div>
  </template>
  <div v-if="connectionOpen && data.connection.can_configure!==false" class="ai-overlay"><section class="ai-modal" role="dialog" aria-modal="true" aria-labelledby="ai-connection-title"><header><h2 id="ai-connection-title">Conexão e custos</h2><button aria-label="Fechar conexão" @click="connectionOpen=false"><X/></button></header><p>Conexão exclusiva desta empresa. A chave é armazenada criptografada e nunca volta para o navegador.</p><div class="ai-price"><strong>Texto · {{data.connection.text_model}}</strong><span>US$ 0,40 entrada · US$ 1,60 saída / milhão de tokens</span><strong>Voz · {{data.connection.voice_model}}</strong><span>Áudio: US$ 32 entrada · US$ 64 saída / milhão de tokens</span><span>Texto na sessão de voz: US$ 4 entrada · US$ 24 saída / milhão de tokens</span><small>Referência em 16/10/2026. Valores do provedor, sem telefonia, WhatsApp, impostos ou câmbio. O valor final depende do consumo; não é uma tarifa fixa por minuto.</small><a :href="data.connection.prices.url" target="_blank" rel="noopener">Consultar preços atuais <ExternalLink :size="13"/></a></div><label>Chave de API OpenAI<input type="password" v-model="key" autocomplete="new-password" :placeholder="data.connection.configured?'Deixe vazio para manter a chave':'Chave do projeto da sua empresa'"></label><details><summary>Telefonia SIP · configuração técnica</summary><label>ID do projeto OpenAI<input v-model="projectId" placeholder="proj_…" maxlength="120"></label><label>Segredo de assinatura do webhook<input type="password" v-model="sipSecret" autocomplete="new-password" placeholder="whsec_… · deixe vazio para manter"></label><p class="ai-help">Usado para validar chamadas recebidas pela rota SIP. Não é a chave de API.</p></details><label>Limite diário de solicitações<input type="number" min="1" max="1000" v-model.number="daily"></label><p class="ai-help">Cada resposta de texto e cada sessão de voz ocupa uma solicitação. Também configure um orçamento no provedor; este limite não é um teto financeiro.</p><label class="ai-check"><input type="checkbox" v-model="enabled">Permitir consumo da API nesta empresa</label><label class="ai-check"><input type="checkbox" v-model="consent">Li os custos e autorizo esta configuração.</label><div v-if="error" class="ai-error">{{error}}</div><button class="primary" @click="saveConnection" :disabled="busy||!consent">Salvar conexão</button></section></div>
  <div v-if="testOpen" class="ai-overlay"><section class="ai-modal ai-lab" role="dialog" aria-modal="true" aria-labelledby="ai-test-title"><header><div><span class="eyebrow">LABORATÓRIO · SEM LIGAR PARA CLIENTES</span><h2 id="ai-test-title">Experimente {{selected.name}}</h2></div><button aria-label="Fechar teste" @click="closeTest"><X/></button></header><div class="ai-test-modes"><button :class="{active:testMode==='local'}" :disabled="voiceStatus!=='idle'" @click="testMode='local';session=null;messages=[]">Simular regras</button><button :class="{active:testMode==='premium'}" :disabled="voiceStatus!=='idle'" @click="testMode='premium';session=null;messages=[]">Texto com IA</button><button :class="{active:testMode==='voice'}" @click="testMode='voice';session=null;messages=[]">Voz ao vivo</button></div><p v-if="testMode==='local'" class="ai-help">Simulação de regras: responde perguntas exatamente iguais à base e verifica passagem humana e descadastro. Não usa modelo generativo nem gera cobrança. Não avalia adaptação emocional, entonação ou naturalidade da voz.</p><template v-else><p class="ai-help">{{(testMode==='voice'?canVoice:canPremium)?'Atendimento disponível para teste.':'Aguardando liberação pela administração DiscAI.'}} Sem chamada telefônica. {{data.connection.managed?'A tecnologia e os limites são gerenciados pela DiscAI.':'O teste utiliza o provedor configurado e pode consumir sua API.'}}</p><label class="ai-check"><input type="checkbox" v-model="consent" :disabled="voiceStatus!=='idle'">Iniciar uma conversa de teste com o recurso disponibilizado.</label></template><details v-if="config.adaptive_conversation" class="ai-scenarios"><summary>Roteiros para testar · {{locales[config.language]}}</summary><p>Escolha uma situação. A seleção apenas prepara o roteiro; não inicia testes nem consome a API.</p><div class="ai-scenario-options"><button v-for="item in scenarios" :key="item.id" :class="{active:scenario?.id===item.id}" @click="chooseScenario(item)">{{item.label}}</button></div><div v-if="scenario" class="ai-scenario-card"><strong>{{testMode==='voice'?'Diga ao microfone quando iniciar:':'Mensagem para experimentar:'}}</strong><blockquote>{{scenario.phrases[config.language]}}</blockquote><small>Observe: {{scenario.expect}}</small><p v-if="testMode==='local'">A simulação gratuita verifica regras de encaminhamento e interrupção. Avalie a adaptação conversando com a IA; para tom e ritmo, use o teste de voz após autorizar os custos.</p><p v-else>Repita com entonações diferentes e corrija a interpretação do agente. Avalie se ele respeita sua correção, evita suposições e mantém as informações aprovadas.</p></div></details><div v-if="error" class="ai-error" role="alert">{{error}}</div><template v-if="testMode!=='voice'"><button v-if="!session" class="primary" @click="startText" :disabled="busy||(testMode==='premium'&&(!canPremium||!consent))"><Play :size="16"/>Iniciar teste</button><template v-else><div class="ai-chat"><div v-for="(m,i) in messages" :key="i" :class="['ai-bubble',m.role]"><small>{{m.role==='user'?'Você':selected.name}}</small><p>{{m.text}}</p><span v-if="m.action&&m.action!=='reply'" class="ai-pill">{{m.action==='stop'?'Interrupção de contato':'Passagem para a equipe'}}</span></div></div><form class="ai-inline" @submit.prevent="send"><input v-model="input" placeholder="Converse com o agente…" aria-label="Mensagem de teste" maxlength="2000" :disabled="busy||session.ended"><button class="primary" :disabled="busy||!input.trim()||session.ended" aria-label="Enviar mensagem"><Send :size="18"/></button></form><button v-if="session.ended" class="secondary" @click="session=null;messages=[]">Novo teste</button></template></template><template v-else><div class="ai-voice-stage"><div :class="['ai-orb',voiceStatus!=='idle'?'listening':'']"><Mic :size="38"/></div><h3>{{({idle:'Pronto para conversar',connecting:'Conectando o microfone…',listening:'Ouvindo você',speaking:'Agente falando'})[voiceStatus]}}</h3><p>Até {{config.max_seconds/60}} minutos · {{locales[config.language]}} · {{config.voice}}</p><button v-if="voiceStatus==='idle'" class="primary" @click="startVoice" :disabled="busy||!canVoice||!consent">Conversar com o agente</button><button v-else class="secondary" @click="stopVoice">Encerrar conversa</button></div><pre v-if="voiceTranscript" class="ai-transcript">{{voiceTranscript}}</pre></template></section></div>
  <div v-if="history" class="ai-overlay"><section class="ai-modal" role="dialog" aria-modal="true" aria-label="Detalhes da conversa"><header><h2>Detalhes da conversa</h2><button @click="history=null" aria-label="Fechar detalhes"><X/></button></header><p>{{history.session.summary||'Sem resumo registrado.'}}</p><p class="ai-help">{{history.session.mode==='local'?'Simulação sem IA generativa':'Conversa com IA'}} · {{history.session.status}}</p><div class="ai-chat"><template v-for="t in history.turns"><div v-if="t.input" class="ai-bubble user"><small>Cliente / teste</small><p>{{t.input}}</p></div><div class="ai-bubble assistant"><small>Agente · {{t.status}} · {{t.latency_ms??'—'}} ms</small><p>{{t.output}}</p></div></template></div><p v-if="history.session.channel==='phone'" class="ai-help">Neste histórico ficam as falas do agente. Não há gravação de áudio nem transcrição da fala do cliente nesta etapa.</p><p v-if="history.session.channel==='voice'" class="ai-help">O teste de voz não grava áudio. A transcrição exibida durante o teste fica apenas no navegador.</p></section></div>
  <div v-if="leaveAction" class="ai-overlay"><section class="ai-modal" role="dialog" aria-modal="true" aria-label="Sair do agente"><h2>Concluir esta edição?</h2><p>Há alterações não salvas ou uma conversa de voz em andamento.</p><div class="ai-inline"><button class="secondary" @click="leaveAction=null">Continuar aqui</button><button class="primary" @click="discard">Descartar e sair</button></div></section></div>
 </div>
